  Widget statsPage(){final last=List.generate(7,(i){final d=DateTime.now().subtract(Duration(days:6-i)).toIso8601String().substring(0,10);return meals.where((m)=>m.date==d).fold<int>(0,(s,m)=>s+m.calories);});final maxValue=last.fold<int>(goal,(a,b)=>a>b?a:b);return ListView(padding:const EdgeInsets.all(16),children:[heading('İstatistikler',sub:'Son 7 günün beslenme özeti'),panel(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Haftalık kalori grafiği',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:20),SizedBox(height:150,child:Row(crossAxisAlignment:CrossAxisAlignment.end,children:List.generate(7,(i){final h=(120*last[i]/maxValue).clamp(2,120).toDouble();return Expanded(child:Padding(padding:const EdgeInsets.symmetric(horizontal:4),child:Column(mainAxisAlignment:MainAxisAlignment.end,children:[Text('${last[i]}',style:const TextStyle(fontSize:9)),Container(height:h,width:22,decoration:BoxDecoration(color:green,borderRadius:BorderRadius.circular(7))),Text(['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'][DateTime.now().subtract(Duration(days:6-i)).weekday-1],style:const TextStyle(fontSize:10))])) ;} )))])),const SizedBox(height:12),Row(children:[Expanded(child:panel(stat('Toplam öğün',meals.length.toString(),Icons.restaurant))),Expanded(child:panel(stat('Bugün kalori','$total',Icons.local_fire_department)))]),heading('Kilo takibi'),panel(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Son kayıt: ${weight.toStringAsFixed(1)} kg',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text('Hedef kilo: ${profile['targetWeight']} kg'),const SizedBox(height:10),FilledButton.icon(onPressed:editWeight,icon:const Icon(Icons.monitor_weight),label:const Text('Bugünkü kilomu güncelle'))]))]);}
  Future<void> manual()async{nameC.clear();kcalC.clear();pC.text='0';cC.text='0';fC.text='0';String slot='Ara öğün';await showDialog(context:context,builder:(d)=>StatefulBuilder(builder:(ctx,ss)=>AlertDialog(title:const Text('Öğün ekle'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[field(nameC,'Yemek adı'),DropdownButtonFormField<String>(value:slot,items:['Kahvaltı','Öğle yemeği','Akşam yemeği','Ara öğün'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>ss(()=>slot=v??slot)),field(kcalC,'Kalori (kcal)',num:true),field(pC,'Protein (g)',num:true),field(cC,'Karbonhidrat (g)',num:true),field(fC,'Yağ (g)',num:true)])),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('İptal')),FilledButton(onPressed:(){final k=int.tryParse(kcalC.text);if(nameC.text.trim().isEmpty||k==null){msg('Yemek adı ve kalori gir.');return;}add(Meal(nameC.text.trim(),today,k,double.tryParse(pC.text)??0,double.tryParse(cC.text)??0,double.tryParse(fC.text)??0,slot));Navigator.pop(d);},child:const Text('Kaydet'))]))));}


