 Future<void> analyze() async {if(apiKey.isEmpty){msg('Önce Ayarlar bölümünden Gemini API anahtarını ekle.');return;}final x=await picker.pickImage(source:ImageSource.gallery,imageQuality:75);if(x==null)return;setState(()=>busy=true);try{final bytes=await x.readAsBytes();final b64=base64Encode(bytes);final uri=Uri.parse('https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=$apiKey');final res=await http.post(uri,headers:{'Content-Type':'application/json'},body:jsonEncode({'contents':[{'parts':[{'text':'Bu yemek fotoğrafını incele. Türkçe kısa JSON ver: name, calories, protein, carbs, fat. Değerleri yaklaşık tahmin et.'},{'inline_data':{'mime_type':'image/jpeg','data':b64}}]}]}));if(res.statusCode!=200)throw Exception('AI yanıtı alınamadı: ${res.statusCode}');final raw=jsonDecode(res.body)['candidates'][0]['content']['parts'][0]['text'].toString().replaceAll('\\`','').replaceAll('```json','').replaceAll('```','').trim();final a=jsonDecode(raw);nameC.text=a['name']??'Yemek';kcalC.text='${a['calories']??0}';pC.text='${a['protein']??0}';cC.text='${a['carbs']??0}';fC.text='${a['fat']??0}';await manual();}catch(e){msg('Fotoğraf analizi başarısız: $e');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> barcode() async {String? code;await showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('Barkod tara'),content:SizedBox(width:280,height:300,child:MobileScanner(onDetect:(capture){if(capture.barcodes.isNotEmpty){code=capture.barcodes.first.rawValue;Navigator.pop(d);}})),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Kapat'))]));if(code==null)return;try{final r=await http.get(Uri.parse('https://world.openfoodfacts.org/api/v2/product/$code.json'));final j=jsonDecode(r.body);final p=j['product'];if(j['status']==1&&p!=null){nameC.text=p['product_name']??'Barkodlu ürün';final n=p['nutriments']??{};kcalC.text='${(n['energy-kcal_100g']??0).round()}';pC.text='${n['proteins_100g']??0}';cC.text='${n['carbohydrates_100g']??0}';fC.text='${n['fat_100g']??0}';await manual();}else{msg('Ürün bulunamadı. Manuel ekleyebilirsin.');}}catch(e){msg('Barkod sorgulanamadı: $e');}}

 Future<void> checkForUpdate() async {try {final r=await http.get(Uri.parse('https://raw.githubusercontent.com/hknkaradogan-cpu/KaloriVision-AI/main/version.json'));if(r.statusCode!=200)return;final data=jsonDecode(r.body);final latest=(data['version']??'1.0.0').toString();if(latest!='1.0.0'&&mounted){await showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('🥳 Yeni güncellemen var!'),content:Text(data['notes']??'KaloriVision AI için yeni özellikler hazır. Yeni sürümü şimdi yüklemek ister misin?'),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Sonra')),FilledButton(onPressed:()async{Navigator.pop(d);final uri=Uri.parse((data['url']??'https://github.com/hknkaradogan-cpu/KaloriVision-AI/releases/latest').toString());await launchUrl(uri,mode:LaunchMode.externalApplication);},child:const Text('Güncelle'))]));}}catch(_){}}

